<script setup lang="ts">import type{Signal}from'../types';import{expired,finite}from'../utils';const p=defineProps<{signal:Signal}>()</script><template><q-card flat bordered class="signal" :class="signal.side.toLowerCase()"><header><q-badge :color="signal.side==='BUY'?'positive':signal.side==='SELL'?'negative':'grey'">{{signal.side}}</q-badge><b>{{signal.symbol}}</b><span>{{signal.quality_class||'—'}} · {{signal.score}}</span></header><div>Entry {{finite(signal.entry_low)}}–{{finite(signal.entry_high)}}</div><div>SL {{finite(signal.stop_loss)}} · TP1 {{finite(signal.take_profit_1)}} · TP2 {{finite(signal.take_profit_2)}}</div><q-chip dense :color="expired(signal.expires_at)?'grey':'primary'">{{expired(signal.expires_at)?'Expired':'Active'}}</q-chip><small>{{signal.reasons?.join(' · ')}}</small></q-card></template>
